import{_ as t,o as a,c as i,ae as s}from"./chunks/framework.RRduUuAx.js";const u=JSON.parse('{"title":"Context Switch Propagation, Keyboard Shortcuts, and End-to-End Tests","description":"","frontmatter":{"work_package_id":"WP03","title":"Context Switch Propagation, Keyboard Shortcuts, and End-to-End Tests","lane":"done","dependencies":["WP02"],"base_branch":"016-workspace-lane-session-ui-tabs-WP02","base_commit":"f90602393e7931f79e1b30beb7fc109e342cb183","created_at":"2026-03-01T13:35:32.740579+00:00","subtasks":["T012","T013","T014","T015","T016"],"phase":"Phase 3 - Integration and Hardening","assignee":"","agent":"claude-haiku","shell_pid":"80432","review_status":"approved","reviewed_by":"Koosha Paridehpour","history":[{"timestamp":"2026-02-27T00:00:00Z","lane":"planned","agent":"system","shell_pid":"","action":"Prompt generated via /spec-kitty.tasks"}]},"headers":[],"relativePath":"specs/016-workspace-lane-session-ui-tabs/tasks/WP03-context-switch-propagation-and-keyboard-shortcuts.md","filePath":"specs/016-workspace-lane-session-ui-tabs/tasks/WP03-context-switch-propagation-and-keyboard-shortcuts.md"}'),o={name:"specs/016-workspace-lane-session-ui-tabs/tasks/WP03-context-switch-propagation-and-keyboard-shortcuts.md"};function n(l,e,r,c,d,p){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="work-package-prompt-wp03-context-switch-propagation-keyboard-shortcuts-and-end-to-end-tests" tabindex="-1">Work Package Prompt: WP03 - Context Switch Propagation, Keyboard Shortcuts, and End-to-End Tests <a class="header-anchor" href="#work-package-prompt-wp03-context-switch-propagation-keyboard-shortcuts-and-end-to-end-tests" aria-label="Permalink to &quot;Work Package Prompt: WP03 - Context Switch Propagation, Keyboard Shortcuts, and End-to-End Tests&quot;">​</a></h1><h2 id="objectives-success-criteria" tabindex="-1">Objectives &amp; Success Criteria <a class="header-anchor" href="#objectives-success-criteria" aria-label="Permalink to &quot;Objectives &amp; Success Criteria&quot;">​</a></h2><ul><li>Implement atomic context switch propagation that updates all visible tabs or shows stale indicators.</li><li>Implement configurable keyboard shortcuts for all tab operations.</li><li>Implement stale-context indicator for tabs that fail to update.</li><li>Deliver Playwright end-to-end tests and performance benchmarks.</li></ul><p>Success criteria:</p><ul><li>After a lane context switch, all visible tabs reflect the new context within 500ms.</li><li>Keyboard shortcuts navigate all tabs and perform common actions without mouse.</li><li>Failed tab updates display a stale-context indicator rather than hiding the problem.</li><li>Zero mixed-context states across tabs in the test matrix.</li><li>Tab switch latency under 200ms at p95.</li></ul><h2 id="context-constraints" tabindex="-1">Context &amp; Constraints <a class="header-anchor" href="#context-constraints" aria-label="Permalink to &quot;Context &amp; Constraints&quot;">​</a></h2><ul><li>Constitution: <code>docs/reference/constitution.md</code></li><li>Plan: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/016-workspace-lane-session-ui-tabs/plan.md</code></li><li>Spec: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/016-workspace-lane-session-ui-tabs/spec.md</code></li><li>Tab surfaces: <code>apps/desktop/src/tabs/</code> (WP01/WP02)</li><li>Context store: <code>apps/desktop/src/tabs/context_switch.ts</code> (WP01)</li><li>Internal event bus: <code>apps/runtime/src/protocol/bus.ts</code> (spec 001)</li></ul><p>Constraints:</p><ul><li>No mouse-required workflows.</li><li>Keyboard shortcuts must be configurable and persisted.</li><li>Keep files under 500 lines.</li><li>TypeScript + Bun + ElectroBun.</li></ul><p>Implementation command:</p><ul><li><code>spec-kitty implement WP03</code></li></ul><h2 id="subtasks-detailed-guidance" tabindex="-1">Subtasks &amp; Detailed Guidance <a class="header-anchor" href="#subtasks-detailed-guidance" aria-label="Permalink to &quot;Subtasks &amp; Detailed Guidance&quot;">​</a></h2><h3 id="subtask-t012-implement-atomic-context-switch-propagation" tabindex="-1">Subtask T012 - Implement atomic context switch propagation <a class="header-anchor" href="#subtask-t012-implement-atomic-context-switch-propagation" aria-label="Permalink to &quot;Subtask T012 - Implement atomic context switch propagation&quot;">​</a></h3><ul><li>Purpose: ensure all visible tabs update when the active context changes, with stale indicators on failure.</li><li>Steps: <ol><li>Implement context propagation in <code>apps/desktop/src/tabs/context_switch.ts</code>: a. On context change, iterate all registered tab surfaces. b. Call <code>onContextChange(newContext)</code> on each tab. c. Track success/failure for each tab. d. If all succeed: clear any stale indicators. e. If any fail: set stale-context flag on failed tabs, log errors.</li><li>Implement propagation timeout: a. Each tab has 500ms to complete its context update. b. If a tab exceeds the timeout, mark it as stale.</li><li>Implement rapid-switch handling: a. If a new context change arrives while propagation is in progress, cancel the current propagation. b. Start propagation for the new context. c. Ensure tabs converge on the final context without rendering intermediates.</li><li>FR-016-003: update all visible tabs when active lane/session changes.</li><li>FR-016-005: display stale-context indicator on failed tabs.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/src/tabs/context_switch.ts</code></li></ul></li><li>Validation: <ul><li>Unit test: change context, verify all tabs receive new context.</li><li>Unit test: simulate tab update failure, verify stale indicator set.</li><li>Unit test: rapid context changes, verify tabs converge on final context.</li><li>Unit test: propagation timeout, verify stale indicator on slow tab.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t013-implement-configurable-keyboard-shortcuts" tabindex="-1">Subtask T013 - Implement configurable keyboard shortcuts <a class="header-anchor" href="#subtask-t013-implement-configurable-keyboard-shortcuts" aria-label="Permalink to &quot;Subtask T013 - Implement configurable keyboard shortcuts&quot;">​</a></h3><ul><li>Purpose: enable keyboard-first tab navigation and common actions.</li><li>Steps: <ol><li>Implement <code>KeyboardShortcuts</code> in <code>apps/desktop/src/tabs/keyboard_shortcuts.ts</code>: a. Define default shortcut map: i. <code>Cmd/Ctrl+1</code> through <code>Cmd/Ctrl+5</code>: switch to terminal, agent, session, chat, project tabs. ii. <code>Cmd/Ctrl+[</code>: previous tab. iii. <code>Cmd/Ctrl+]</code>: next tab. iv. <code>Cmd/Ctrl+Shift+T</code>: focus tab bar. b. Implement shortcut registration with the ElectroBun keyboard event system. c. Implement shortcut configuration UI (or config file): users can remap shortcuts. d. Persist shortcut configuration to <code>~/.helios/data/keyboard_shortcuts.json</code>.</li><li>Implement focus management: a. When a tab is activated via shortcut, focus moves into the tab content. b. Tab/Shift-Tab within a tab moves focus between focusable elements. c. Escape returns focus to the tab bar.</li><li>Implement shortcut conflict detection: a. If a user maps a shortcut that conflicts with a system shortcut, warn and reject.</li><li>FR-016-004: provide configurable keyboard shortcuts for switching between tabs.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/src/tabs/keyboard_shortcuts.ts</code></li></ul></li><li>Validation: <ul><li>Unit test: register default shortcuts, verify each activates the correct tab.</li><li>Unit test: remap a shortcut, verify new mapping works.</li><li>Unit test: conflict detection rejects duplicate shortcut.</li><li>Unit test: persistence: save shortcuts, reload, verify mappings preserved.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t014-implement-stale-context-indicator-component" tabindex="-1">Subtask T014 - Implement stale-context indicator component <a class="header-anchor" href="#subtask-t014-implement-stale-context-indicator-component" aria-label="Permalink to &quot;Subtask T014 - Implement stale-context indicator component&quot;">​</a></h3><ul><li>Purpose: visually communicate to the user when a tab&#39;s content may be out of date.</li><li>Steps: <ol><li>Implement stale indicator in the tab bar header: a. When a tab&#39;s <code>staleContext</code> flag is set, display a warning icon/badge on its tab header. b. Use a distinct color (yellow/amber) that does not overlap with active/inactive styling.</li><li>Implement stale indicator within the tab content: a. Display a non-dismissible banner at the top of the tab content: &quot;This tab may show outdated information. Try switching lanes again.&quot; b. Provide a &quot;Retry&quot; button that re-triggers context propagation for this tab only.</li><li>Implement auto-clear: a. If a subsequent context change succeeds, clear the stale indicator. b. If the retry action succeeds, clear the stale indicator.</li><li>Emit <code>tab.context.stale</code> event on the bus for monitoring.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/src/tabs/tab_bar.ts</code> (header indicator)</li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/src/tabs/tab_surface.ts</code> (content banner)</li></ul></li><li>Validation: <ul><li>Unit test: set stale flag, verify warning icon and banner displayed.</li><li>Unit test: retry succeeds, verify stale indicator cleared.</li><li>Unit test: subsequent successful context change clears stale.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t015-add-playwright-end-to-end-tests" tabindex="-1">Subtask T015 - Add Playwright end-to-end tests <a class="header-anchor" href="#subtask-t015-add-playwright-end-to-end-tests" aria-label="Permalink to &quot;Subtask T015 - Add Playwright end-to-end tests&quot;">​</a></h3><ul><li>Purpose: validate the complete tab navigation experience from the user&#39;s perspective.</li><li>Steps: <ol><li>Create <code>apps/desktop/tests/e2e/tabs/tab_navigation.test.ts</code>: a. Test: open app, verify 5 tabs visible in tab bar. b. Test: click each tab, verify content updates. c. Test: switch to each tab via keyboard shortcut, verify content. d. Test: cycle through tabs with Cmd+[ and Cmd+], verify order.</li><li>Create <code>apps/desktop/tests/e2e/tabs/context_switch.test.ts</code>: a. Test: switch lane, verify all tabs update to new lane content. b. Test: rapid lane switches (5 switches in 1 second), verify final state is consistent. c. Test: simulate tab update failure, verify stale indicator visible.</li><li>Create <code>apps/desktop/tests/e2e/tabs/keyboard_workflow.test.ts</code>: a. Test: complete full workflow using only keyboard: i. Open workspace -&gt; switch to terminal tab -&gt; switch lanes -&gt; view agent output -&gt; open chat. b. Test: focus management (Tab/Shift-Tab within tab content, Escape to tab bar).</li><li>Capture screenshots for visual regression baseline.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/tests/e2e/tabs/tab_navigation.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/tests/e2e/tabs/context_switch.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/tests/e2e/tabs/keyboard_workflow.test.ts</code></li></ul></li><li>Parallel: Yes (after T012-T014 are integrated).</li></ul><h3 id="subtask-t016-add-performance-benchmarks" tabindex="-1">Subtask T016 - Add performance benchmarks <a class="header-anchor" href="#subtask-t016-add-performance-benchmarks" aria-label="Permalink to &quot;Subtask T016 - Add performance benchmarks&quot;">​</a></h3><ul><li>Purpose: validate tab switch latency and context propagation timing SLOs.</li><li>Steps: <ol><li>Create <code>apps/desktop/tests/e2e/tabs/performance.test.ts</code>: a. Tab switch benchmark: switch between all 5 tabs 50 times, measure render latency, assert p95 &lt; 200ms. b. Context propagation benchmark: trigger 20 lane switches, measure propagation to all tabs, assert p95 &lt; 500ms. c. Rapid switch benchmark: 10 lane switches in 2 seconds, measure final convergence time.</li><li>Record timing distributions for review.</li><li>Verify input latency stays under 100ms during background data loading (NFR-016-003).</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/tests/e2e/tabs/performance.test.ts</code></li></ul></li><li>Parallel: Yes (after T012-T014 are integrated).</li></ul><h2 id="test-strategy" tabindex="-1">Test Strategy <a class="header-anchor" href="#test-strategy" aria-label="Permalink to &quot;Test Strategy&quot;">​</a></h2><ul><li>Playwright for full UI interaction and keyboard workflow verification.</li><li>Performance benchmarks with timing assertions at p95.</li><li>Visual regression screenshots at key states.</li><li>Aim for &gt;=85% line coverage across tab modules.</li></ul><h2 id="risks-mitigations" tabindex="-1">Risks &amp; Mitigations <a class="header-anchor" href="#risks-mitigations" aria-label="Permalink to &quot;Risks &amp; Mitigations&quot;">​</a></h2><ul><li>Risk: rapid context switches cause flicker.</li><li>Mitigation: debounced propagation with cancel-on-new-change.</li><li>Risk: keyboard shortcut conflicts with system shortcuts.</li><li>Mitigation: conflict detection and user warning on remap.</li></ul><h2 id="review-guidance" tabindex="-1">Review Guidance <a class="header-anchor" href="#review-guidance" aria-label="Permalink to &quot;Review Guidance&quot;">​</a></h2><ul><li>Confirm atomic propagation either updates all tabs or shows stale indicators.</li><li>Confirm rapid switch handling converges to final context without intermediate renders.</li><li>Confirm all Playwright tests use only keyboard for keyboard workflow tests.</li><li>Confirm performance benchmarks use sufficient iterations.</li></ul><h2 id="activity-log" tabindex="-1">Activity Log <a class="header-anchor" href="#activity-log" aria-label="Permalink to &quot;Activity Log&quot;">​</a></h2><ul><li>2026-02-27T00:00:00Z -- system -- lane=planned -- Prompt created.</li><li>2026-03-01T13:35:33Z – claude-haiku – shell_pid=80432 – lane=doing – Assigned agent via workflow command</li><li>2026-03-01T13:37:09Z – claude-haiku – shell_pid=80432 – lane=done – Implemented WP03</li></ul>',30)])])}const b=t(o,[["render",n]]);export{u as __pageData,b as default};
